parameters.jsCode:
const s = $('Set search settings').first().json;
const flag = (v) => v !== false && v !== 'false' && v !== 0 && v !== '0' && v !== '';
const toneFilter = String(s.toneFilter || 'any').trim().toLowerCase();

const out = [];
for (const item of $input.all()) {
  const a = item.json || {};
  // HTTP error payloads or empty actor responses have no article URL
  if (!a.url && !a.title) continue;

  if (toneFilter && toneFilter !== 'any') {
    const sent = String(a.sentiment || '').trim().toLowerCase();
    if (toneFilter === 'negative' && sent !== 'negative') continue;
    if (toneFilter === 'positive' && sent !== 'positive') continue;
    if (toneFilter === 'non-neutral' && sent !== 'negative' && sent !== 'positive') continue;
  }

  out.push({ json: a });
}
return out;

const logged = new Set(
  $('Get existing article URLs').all()
    .map((i) => String(i.json.url ?? '').trim())
    .filter(Boolean)
);
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const a = item.json || {};
  const url = String(a.url ?? '').trim();
  if (!url || logged.has(url) || seen.has(url)) continue;
  seen.add(url);
  out.push({ json: a });
}
return out;

const join = (v) => Array.isArray(v) ? v.filter(Boolean).join('; ') : (v ?? '');
const str = (v) => (v === null || v === undefined) ? '' : String(v);

return $input.all()
  .map((item) => item.json || {})
  .filter((a) => a.url != null && String(a.url).trim() !== '')
  .map((a) => ({
    json: {
      url: str(a.url).trim(),
      title: str(a.title),
      domain: str(a.domain),
      sourceCountry: str(a.sourceCountry),
      language: str(a.language),
      seenAt: str(a.seenAt),
      sentiment: str(a.sentiment),
      toneRange: str(a.toneRange),
      query: str(a.query),
      loggedAt: $now.toISO(),
    }
  }));

const mentions = $input.all()
  .map((i) => i.json)
  .filter((j) => j && j.url != null && String(j.url).trim() !== '');

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const rows = mentions.slice(0, 50).map((a) => {
  const title = esc(a.title) || '(no title)';
  const href = esc(a.url);
  const linked = a.url ? `<a href="${href}">${title}</a>` : title;
  return `<tr>
  <td>${esc(a.seenAt)}</td>
  <td>${linked}</td>
  <td>${esc(a.domain)}</td>
  <td>${esc(a.sourceCountry)}</td>
  <td>${esc(a.sentiment)}</td>
</tr>`;
}).join('');

const count = mentions.length;
const digestHtml = `<p>Today's run found <strong>${count}</strong> new mention${count === 1 ? '' : 's'} that passed your filters and were not already in your sheet.</p>
<table border="1" cellpadding="6" cellspacing="0">
  <thead>
    <tr>
      <th>Seen (UTC)</th>
      <th>Title</th>
      <th>Outlet</th>
      <th>Country</th>
      <th>Tone</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>
<p>Showing up to 50 rows. All new mentions were appended to your Google Sheet.</p>`;

return [{ json: { mentions, count, digestHtml } }];
